PRAGMA defer_foreign_keys=ON;
CREATE TABLE family_notification_request_sources(version_id TEXT PRIMARY KEY REFERENCES family_notification_versions(id) DEFERRABLE INITIALLY DEFERRED,kind TEXT NOT NULL CHECK(kind IN('legacy_unknown','family_request')),request_id TEXT REFERENCES family_request_roots(id),request_revision INTEGER,request_event_id TEXT REFERENCES family_request_events(id),snapshot_json TEXT,CHECK(kind='legacy_unknown' AND request_id IS NULL AND request_revision IS NULL AND request_event_id IS NULL AND snapshot_json IS NULL OR kind='family_request' AND request_id IS NOT NULL AND request_revision>0 AND request_event_id IS NOT NULL AND json_valid(snapshot_json)));
INSERT INTO family_notification_request_sources(version_id,kind) SELECT id,'legacy_unknown' FROM family_notification_versions;
ALTER TABLE family_notification_versions ADD COLUMN source_kind TEXT NOT NULL DEFAULT 'legacy_unknown' CHECK(source_kind IN('legacy_unknown','none','family_request'));
ALTER TABLE family_notification_versions ADD COLUMN source_ref_id TEXT REFERENCES family_notification_request_sources(version_id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE family_notification_versions ADD COLUMN source_request_id TEXT REFERENCES family_request_roots(id);
ALTER TABLE family_notification_versions ADD COLUMN source_request_revision INTEGER;
CREATE TRIGGER family_notification_declared_source BEFORE INSERT ON family_notification_versions BEGIN SELECT CASE WHEN NEW.source_kind NOT IN('none','family_request') OR NEW.source_kind='none' AND (NEW.source_ref_id IS NOT NULL OR NEW.source_request_id IS NOT NULL OR NEW.source_request_revision IS NOT NULL) OR NEW.source_kind='family_request' AND (NEW.action<>'publish' OR NEW.source_ref_id IS NOT NEW.id OR NEW.source_request_id IS NULL OR NEW.source_request_revision IS NULL OR NEW.source_request_revision<1) THEN RAISE(ABORT,'notification explicit declared original business source') END;END;
CREATE TRIGGER family_notification_request_source BEFORE INSERT ON family_notification_request_sources BEGIN SELECT CASE WHEN NEW.kind<>'family_request' OR NOT EXISTS(SELECT 1 FROM family_notification_versions v JOIN family_request_roots r ON r.id=NEW.request_id JOIN family_request_events e ON e.id=NEW.request_event_id AND e.root_id=r.id WHERE v.id=NEW.version_id AND v.action='publish' AND v.source_kind='family_request' AND v.source_ref_id=v.id AND v.source_request_id=r.id AND v.source_request_revision=NEW.request_revision AND e.revision=NEW.request_revision AND e.revision=(SELECT max(revision) FROM family_request_events WHERE root_id=r.id) AND r.customer_id=v.customer_id AND r.recipient_id=v.recipient_id AND r.store_id=v.store_id AND e.created_at<=v.created_at AND NEW.snapshot_json IS json_object('request_id',r.id,'request_number',r.request_number,'title',r.title,'request_kind',r.request_kind,'time_status',r.time_status,'requested_start',r.requested_start,'requested_end',r.requested_end,'request_note',r.request_note,'event_id',e.id,'revision',e.revision,'action',e.action,'status',e.status,'public_note',e.public_note,'created_at',e.created_at,'source',CASE WHEN e.created_by=r.recipient_id THEN 'family' ELSE 'staff' END)) THEN RAISE(ABORT,'notification fixed current named public request source') END;END;
CREATE TRIGGER family_notification_request_sources_no_update BEFORE UPDATE ON family_notification_request_sources BEGIN SELECT RAISE(ABORT,'notification business source immutable');END;
CREATE TRIGGER family_notification_request_sources_no_delete BEFORE DELETE ON family_notification_request_sources BEGIN SELECT RAISE(ABORT,'notification business source immutable');END;
